# -*- coding: utf-8 -*-
from odoo import fields, models


class AccountMove(models.Model):
    _inherit = 'account.move'

    fiscalyear_closing_id = fields.Many2one(
        'account.fiscalyear.closing',
        string='Retained Earnings Closing',
        readonly=True, copy=False,
        help="Set automatically when this entry is the year-end closing "
             "entry generated by the Automatic Retained Earnings module. "
             "Its own lines are excluded from future closings so a period "
             "can never be closed twice.")
